<script setup>
import {ref} from 'vue'
import FormPanel from './FormPanel.vue'
import {apiRequest} from '../services/api.js'
import {today} from '../utils.js'
const emit=defineEmits(['saved']),props=defineProps({initial:Object,parentId:Number}),busy=ref(false),error=ref(''),notice=ref('')
const f=(name,label,extra={})=>({name,label,...extra}),choices=a=>a.map(([value,label])=>({value,label}))
const fields=[f('name','Nome'),f('cycle','Ciclo'),f('objective','Objetivo',{type:'textarea'}),f('kind','Tipo',{options:choices([['return_call','Convocação de retorno'],['reminder','Lembrete'],['orientation','Orientação ou hábito'],['incentive','Incentivo'],['offline','Desplugada']])}),f('main_metric','Indicador principal',{options:choices([['response','Resposta'],['on_time','Retorno no prazo'],['attendance','Comparecimento'],['checkin','Check-in respondido'],['adherence','Adesão ao plano']])}),f('start_date','Início',{type:'date',default:today()}),f('end_date','Encerramento',{type:'date'}),f('measurement_from','Medição: início',{type:'date',default:today()}),f('measurement_to','Medição: fim',{type:'date'}),f('unit','Unidade',{optional:true}),f('contents','Conteúdos vinculados (referências)',{type:'textarea',optional:true}),f('filter_status','Status do público',{default:'ATIVO',options:choices([['ATIVO','Ativo'],['INATIVO','Inativo']])}),...['risk','company','shift','care_line'].map(k=>f('filter_'+k,({risk:'Risco (1 a 4)',company:'Empresa',shift:'Turno',care_line:'Linha de cuidado'})[k],{optional:true})),f('channel','Canal',{options:choices([['whatsapp','WhatsApp simulado'],['phone','Ligação'],['onsite','Presencial'],['dds','DDS'],['poster','Mural']])}),f('text_a','Texto da variante A',{type:'textarea'}),f('text_b','Texto da variante B (opcional)',{type:'textarea',optional:true}),f('send_time','Horário de envio',{type:'time',default:'14:30'}),f('comparison','Comparação',{options:choices([['ab','A/B estável por hash da matrícula'],['stepped','Implantação escalonada'],['historical','Linha de base histórica (mais fraca)']])}),...Object.entries({minimum_gain_pp:['Meta de ganho (pontos)',4],max_cost:['Teto por retorno recuperado (R$)',126],message_cost:['Mensagem (R$)',.05],hour_cost:['Hora de enfermagem (R$) · estimativa',25],benefit_cost:['Benefício por resgate (R$)',0]}).map(([name,[label,value]])=>f(name,label,{type:'number',min:0,step:.01,default:value}))]
async function save(d){busy.value=true;error.value='';try{const r=await apiRequest(props.parentId?'/experiments/'+props.parentId+'/versions':'/experiments','POST',d);notice.value='Campanha salva. Público congelado: '+r.frozen_count+' pessoas.';emit('saved',r)}catch(e){error.value=e.message}finally{busy.value=false}}
</script><template><section class="card card-body mb-3"><h2 class="h5">{{parentId?'Criar nova versão':'Nova campanha de engajamento'}}</h2><p class="small">Simulação com gravação na sua visita. Critérios não expõem nomes. Público congelado no início; campanhas futuras exigem Iniciar quando chegar a data.</p><p v-if="error" class="alert alert-danger">{{error}}</p><p v-if="notice" class="alert alert-success">{{notice}}</p><FormPanel :key="parentId||0" :fields="fields" :initial="initial" :busy="busy" submit-label="Salvar campanha" @submit="save"/></section></template>
